const app={mode:'citizen',role:'citizen',page:'home',summary:null,products:[],orders:[],busy:false,profile:loadProfile(),access:loadAccess(),lastUpdated:null,watchId:null,lastGpsSent:0,selectedBooking:null,staffUser:''};
const navs={
 citizen:[['home','⌂','Overview'],['pickups','▤','My bookings'],['book','＋','Book a pickup'],['market','◈','Materials market']],
 operator:[['dispatch','▦','Live dispatch'],['bookings','▤','All bookings'],['map','⌖','Operations map']],
 transporter:[['dispatch','▣','My assigned jobs'],['map','⌖','Live map']],
 recycler:[['intake','⇣','Incoming loads'],['processing','⟳','Recovery records'],['inventory','◈','Product inventory'],['buyers','◎','Buyer network'],['guide','▧','Materials guide']]
};
const names={requested:'Request received',assigned:'Vehicle assigned',picked_up:'Picked up',in_transit:'In transit',received:'Facility received',processing:'Processing',recovered:'Recovery recorded',closed:'Closed',rejected:'Request rejected'};
const wasteTypes=['Concrete & brick','Mixed C&D','Tiles & ceramics','Soil & rubble','Wood & metals','Other C&D'];
const materials=[
 {name:'Recycled concrete aggregate',type:'Concrete / masonry',route:'Crush, screen and grade into size bands such as 5–10, 10–20 or 20–40 mm.',uses:'Road layers and approved concrete or precast applications, only when the specific grading, strength, absorption and project requirements are met.',caution:'Do not infer structural suitability from the material name. Record test report and intended application.'},
 {name:'Recycled mixed aggregate',type:'Concrete, brick and rubble',route:'Remove contaminants, crush and screen into a specified gradation.',uses:'Potential road embankment, granular sub-base, stabilized base and paving products under applicable project specifications.',caution:'Use only in a tested application; mixed aggregate is not interchangeable with certified natural aggregate.'},
 {name:'Fine aggregate / manufactured sand',type:'Processed mineral fines',route:'Wash or classify fine fractions; document particle-size distribution and contamination checks.',uses:'The 2025 C&D Rules list fine aggregates among direct outputs. Application depends on product quality and the relevant specification.',caution:'Record source, grading and test evidence. Avoid claiming potable, structural or unrestricted use.'},
 {name:'Bricks, blocks and tiles',type:'Recycled mineral products',route:'Manufacture from processed C&D feedstock and log batch, dimensions and quality tests.',uses:'The 2025 Rules list bricks, blocks, tiles and hollow bricks as downstream products.',caution:'Suitability depends on applicable product standard, performance testing and the construction design.'},
 {name:'Pavers and kerbs',type:'Recycled mineral products',route:'Use suitable graded aggregate in a controlled precast mix; maintain batch and curing records.',uses:'Pavers and kerb stones are listed as downstream products in the 2025 Rules; road schedules also identify these applications.',caution:'Do not describe as compliant unless test reports and the correct standard are attached.'},
 {name:'Manufactured soil',type:'Processed mineral fines',route:'Process and screen suitable mineral fractions; verify the composition for the intended use.',uses:'Listed as a direct product in the 2025 Rules.',caution:'No landscaping or planting suitability is implied without contaminant and quality testing.'},
 {name:'Recovered steel and other metals',type:'Reusable / resalable stream',route:'Segregate by metal and condition; direct to an appropriate registered downstream buyer.',uses:'Reuse or material recycling. The 2025 Rules treat reusable / resalable streams separately from debris recycling targets.',caution:'Keep weighment, buyer and destination records; this mass is not debris-derived recycled output for target calculations.'},
 {name:'Salvaged timber, glass and plastic',type:'Reusable / resalable stream',route:'Separate clean, usable items for direct reuse; route non-reusable fractions to suitable downstream systems.',uses:'The 2025 Rules place these resalable or reusable streams outside debris-derived utilisation target accounting.',caution:'Do not combine these weights with mineral C&D recycling totals.'}
];
const h=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=1)=>Number(v||0).toLocaleString('en-IN',{minimumFractionDigits:d,maximumFractionDigits:d});
const date=(s,opts={month:'short',day:'numeric',year:'numeric'})=>s?new Intl.DateTimeFormat('en-IN',opts).format(new Date(s)):'—';
const time=s=>s?new Intl.DateTimeFormat('en-IN',{hour:'numeric',minute:'2-digit',day:'numeric',month:'short'}).format(new Date(s)):'—';
const statusClass=s=>s==='in_transit'?'transit':['received','processing'].includes(s)?'processing':['recovered','closed'].includes(s)?'recovered':s==='requested'?'requested':s==='rejected'?'rejected':'';
function loadProfile(){try{return {...{name:'Ananya Rao',phone:'',locality:'',latitude:null,longitude:null},...JSON.parse(localStorage.getItem('debrix-profile')||'{}')}}catch{return {name:'Ananya Rao',phone:'',locality:'',latitude:null,longitude:null}}}
function saveProfile(p){app.profile={...app.profile,...p};localStorage.setItem('debrix-profile',JSON.stringify(app.profile))}
function loadAccess(){try{const x=JSON.parse(localStorage.getItem('debrix-access')||'{}');return {bookings:x.bookings||{},orders:x.orders||{}}}catch{return {bookings:{},orders:{}}}}
function rememberAccess(kind,id,token){if(!['bookings','orders'].includes(kind)||!token)return;app.access[kind][id]=token;localStorage.setItem('debrix-access',JSON.stringify(app.access))}
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;document.querySelector('#toast-region').append(el);setTimeout(()=>el.remove(),4000)}
function setBusy(v){app.busy=v;document.body.classList.toggle('busy',v);document.querySelectorAll('button[data-submit]').forEach(b=>b.disabled=v)}
async function api(path,{method='GET',body}={}){const takeLast=x=>Object.fromEntries(Object.entries(x).slice(-40));const headers={'content-type':'application/json','x-demo-role':app.role,'x-demo-user':app.mode==='citizen'?(app.profile.name||'Ananya Rao'):(app.staffUser||''),'x-debrix-access':JSON.stringify({bookings:takeLast(app.access.bookings),orders:takeLast(app.access.orders)})};const r=await fetch(path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});let data={};try{data=await r.json()}catch{}if(!r.ok){const error=new Error(data.error||`Request failed (${r.status})`);error.status=r.status;throw error}return data}
function roleLabel(){return app.mode==='citizen'?'Citizen':app.role==='operator'?'Operator':app.role==='transporter'?'Transporter':'Recycler / facility'}
function showSync(){const el=document.querySelector('#sync-state');el.classList.toggle('offline',!app.lastUpdated);el.querySelector('span').textContent=app.lastUpdated?`Updated ${new Intl.DateTimeFormat('en-IN',{hour:'numeric',minute:'2-digit'}).format(app.lastUpdated)}`:'Waiting for connection'}
async function reload({quiet=false}={}){if(!quiet&&!app.summary)document.querySelector('#view').innerHTML='<div class="loading"><span class="spinner"></span> Loading your workspace…</div>';try{const [summary,products,orders]=await Promise.all([api('/api/summary'),api('/api/products'),api('/api/orders')]);app.summary=summary;app.products=products.items||[];app.orders=orders.items||[];app.lastUpdated=new Date();showSync();render()}catch(e){showSync();if(e.status===401&&app.mode==='admin'){stopGps();app.mode='citizen';app.role='citizen';app.page='home';app.staffUser='';app.summary=null;app.products=[];app.orders=[];if(!quiet)toast('Administrator session expired. Sign in again to reopen the admin workspace.',true);await reload();return}if(!app.summary){document.querySelector('#view').innerHTML=`<div class="notice error"><strong>DEBRIX could not load data.</strong><p>${h(e.message)}</p><button class="button secondary" id="retry-load">Try again</button></div>`;document.querySelector('#retry-load')?.addEventListener('click',()=>reload())}else if(!quiet)toast(e.message,true)}}
function nav(){const items=navs[app.mode==='citizen'?'citizen':app.role]||navs.citizen;document.querySelector('#nav-list').innerHTML=items.map(([key,icon,label])=>`<button class="nav-item ${app.page===key?'active':''}" data-page="${key}"><span class="nav-icon">${icon}</span><span>${label}</span>${key==='pickups'&&app.mode==='citizen'?`<span class="nav-count">${app.summary?.bookings?.filter(b=>!['closed','recovered','rejected'].includes(b.status)).length||''}</span>`:''}</button>`).join('');document.querySelectorAll('.nav-item').forEach(el=>el.onclick=()=>{stopGpsIfChanging(el.dataset.page);app.page=el.dataset.page;render()});const active=items.find(x=>x[0]===app.page);document.querySelector('#crumb-current').textContent=active?.[2]||'Overview'}
function render(){document.documentElement.dataset.theme=localStorage.getItem('debrix-theme')||'light';document.querySelector('#workspace-label').textContent=app.mode==='citizen'?'CITIZEN PORTAL':'ADMINISTRATOR · '+(app.role==='operator'?'OPERATOR':app.role==='transporter'?'TRANSPORTER':'RECYCLER');document.querySelector('#profile-name').textContent=app.mode==='citizen'?(app.profile.name||'Citizen'):(app.staffUser||'Staff workspace');document.querySelector('#profile-role').textContent=roleLabel();document.querySelector('#avatar').textContent=(app.mode==='citizen'?app.profile.name:app.staffUser)?.[0]||'D';document.querySelector('#citizen-portal').classList.toggle('active',app.mode==='citizen');document.querySelector('#admin-portal').classList.toggle('active',app.mode==='admin');document.querySelector('#admin-tools').classList.toggle('hidden',app.mode!=='admin');document.querySelector('#citizen-portal').classList.toggle('hidden',app.mode==='admin');nav();const f={home:app.mode==='citizen'?citizenHome:adminHome,pickups:citizenBookings,book:bookingPage,market:marketPage,dispatch:adminHome,bookings:allBookings,map:operationsMap,intake:intakePage,processing:processingPage,inventory:inventoryPage,buyers:buyersPage,guide:guidePage};(f[app.page]||citizenHome)();initMapWidgets()}
function heading(title,sub,badge=''){return `<div class="page-heading"><div><p class="eyebrow">${h(roleLabel())}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div>${badge?`<span class="demo-badge">${badge}</span>`:''}</div>`}
function cardTitle(title,sub='',action=''){return `<div class="card-head"><div><h2 class="card-title">${title}</h2>${sub?`<p class="card-subtitle">${sub}</p>`:''}</div>${action}</div>`}
function metric(label,value,meta,icon){return `<article class="card metric-card"><div class="metric-accent"><span class="metric-label">${label}</span><span class="metric-symbol">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-meta">${meta}</div></article>`}
function demoTag(demo){return demo?'<span class="tiny-tag">DEMO</span>':''}
function activeBookings(items=app.summary?.bookings||[]){return items.filter(b=>!['recovered','closed','rejected'].includes(b.status))}
function flow(status){if(status==='rejected')return '<div class="workflow"><div class="workflow-step done"><span class="step-dot">✓</span><span>Request received</span></div><div class="workflow-step current"><span class="step-dot">×</span><span>Request rejected</span></div></div>';const steps=[['requested','Requested'],['assigned','Assigned'],['picked_up','Picked up'],['in_transit','In transit'],['received','Received'],['processing','Sorting'],['recovered','Recovered'],['closed','Complete']];const ix=steps.findIndex(x=>x[0]===status);return `<div class="workflow">${steps.map(([key,label],i)=>`<div class="workflow-step ${i<ix?'done':''} ${i===ix?'current':''}"><span class="step-dot">${i<ix?'✓':i+1}</span><span>${label}</span></div>`).join('')}</div>`}
function activity(b){return `<div class="activity">${(b.events||[]).slice().reverse().map(e=>`<div class="event-row"><span class="event-dot"></span><div class="event-copy"><strong>${h(e.note)}</strong><small>${h(e.actor_name)} · ${h(e.actor_role)} ${demoTag(e.demo)}</small>${e.evidence_ref?`<small>Evidence reference: ${h(e.evidence_ref)}</small>`:''}</div><span class="event-time">${time(e.at)}</span></div>`).join('')||'<div class="empty-state compact">No updates recorded yet.</div>'}</div>`}
function osmLink(lat,lon){if(lat==null||lon==null||!Number.isFinite(Number(lat))||!Number.isFinite(Number(lon))){lat=12.9716;lon=77.5946}lat=Number(lat);lon=Number(lon);return 'https://www.openstreetmap.org/?mlat='+lat.toFixed(6)+'&mlon='+lon.toFixed(6)+'#map=16/'+lat.toFixed(6)+'/'+lon.toFixed(6)}
function mapCard(opts={}){const lat=opts.lat,lon=opts.lon,hasPin=lat!=null&&lon!=null&&Number.isFinite(Number(lat))&&Number.isFinite(Number(lon)),selectable=Boolean(opts.selectable),title=opts.title||'Bengaluru area',updated=opts.updated,demo=opts.demo,emptyNote=opts.emptyNote||'Pickup pin not set. Click the map or use device location.';const centerLat=hasPin?Number(lat):12.9716,centerLon=hasPin?Number(lon):77.5946;const hint=hasPin?'Pinned point · '+centerLat.toFixed(5)+', '+centerLon.toFixed(5)+(updated?' · '+time(updated):''):selectable?'Click the map or drag the pin to choose pickup coordinates.':emptyNote;return '<section class="card map-card"><div class="map-heading"><div><strong>'+h(title)+'</strong><small>'+(hasPin?'Pinned location':'Bengaluru · area context')+'</small></div><a class="text-link" href="'+osmLink(centerLat,centerLon)+'" target="_blank" rel="noreferrer">Open map ↗</a></div><div class="map-canvas" data-debrix-map data-lat="'+(hasPin?centerLat:'')+'" data-lon="'+(hasPin?centerLon:'')+'" data-selectable="'+(selectable?'true':'false')+'" aria-label="OpenStreetMap location map"></div><div class="map-footer"><span data-map-hint>'+h(hint)+'</span>'+(demo?demoTag(true):'')+'</div></section>'}
function syncPickupPin(lat,lon){const form=document.querySelector('#booking-form');if(!form)return;form.elements.latitude.value=Number(lat).toFixed(6);form.elements.longitude.value=Number(lon).toFixed(6);saveProfile({latitude:Number(lat),longitude:Number(lon),locality:form.elements.locality.value});const state=document.querySelector('#pickup-pin-state');if(state)state.textContent='Pickup pin set · '+Number(lat).toFixed(5)+', '+Number(lon).toFixed(5)}
function initMapWidgets(root=document){const maps=root.querySelectorAll('[data-debrix-map]:not([data-map-ready])');maps.forEach(el=>{el.dataset.mapReady='true';const hint=el.closest('.map-card')?.querySelector('[data-map-hint]');if(!window.L){if(hint)hint.textContent='The interactive map library did not load. You can still enter the address or use device location.';return}const hasPin=el.dataset.lat!==''&&el.dataset.lon!=='';const selectedLat=hasPin?Number(el.dataset.lat):12.9716,selectedLon=hasPin?Number(el.dataset.lon):77.5946,selectable=el.dataset.selectable==='true';const map=L.map(el,{scrollWheelZoom:false}).setView([selectedLat,selectedLon],hasPin?16:12);const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);tiles.on('tileerror',()=>{if(hint)hint.textContent=selectable?'Map tiles are temporarily unavailable. You may still place a pin on the map or use device location.':'Map tiles are temporarily unavailable. Use Open map to view this reported point.'});let marker=null;if(hasPin)marker=L.marker([selectedLat,selectedLon],{draggable:selectable}).addTo(map);const choose=point=>{const lat=Number(point.lat.toFixed(6)),lon=Number(point.lng.toFixed(6));if(marker)marker.setLatLng([lat,lon]);else{marker=L.marker([lat,lon],{draggable:true}).addTo(map);if(selectable)marker.on('dragend',e=>choose(e.target.getLatLng()))}el.dataset.lat=String(lat);el.dataset.lon=String(lon);map.setView([lat,lon],Math.max(16,map.getZoom()));if(hint)hint.textContent='Pickup pin set · '+lat.toFixed(5)+', '+lon.toFixed(5);if(selectable)syncPickupPin(lat,lon)};if(selectable){map.on('click',e=>choose(e.latlng));if(marker)marker.on('dragend',e=>choose(e.target.getLatLng()))}map.whenReady(()=>setTimeout(()=>map.invalidateSize(),80))})}
function evidenceList(b){const refs=[['Facility receipt',b.receipt_evidence],['Recovery record',b.evidence_ref]].filter(x=>x[1]);const files=Array.isArray(b.evidence)?b.evidence:[];return '<section class="evidence-panel"><h3>Supporting evidence</h3>'+(refs.length?'<div class="evidence-refs">'+refs.map(x=>'<p><strong>'+h(x[0])+':</strong> '+h(x[1])+'</p>').join('')+'</div>':'<p class="helper">No evidence reference has been recorded.</p>')+(files.length?'<div class="evidence-files">'+files.map(file=>'<div class="evidence-file"><span>▤</span><span><strong>'+h(file.name)+'</strong><small>'+h(file.kind==='receipt'?'Facility receipt':'Processing / recovery')+' · '+n(Number(file.size||0)/1024,0)+' KB · '+time(file.added_at)+'</small></span><button type="button" class="button small secondary" data-booking-id="'+h(b.id)+'" data-evidence-download="'+h(file.id)+'" data-filename="'+h(file.name)+'">Download evidence</button></div>').join('')+'</div>':'<p class="helper">No file attached. The recorded evidence reference remains visible.</p>')+'</section>'}
async function downloadEvidence(bookingId,evidenceId,fileName){try{const access=Object.fromEntries(Object.entries(app.access.bookings).slice(-40));const response=await fetch('/api/bookings/'+encodeURIComponent(bookingId)+'/evidence/'+encodeURIComponent(evidenceId),{credentials:'same-origin',headers:{'x-demo-role':app.role,'x-demo-user':app.mode==='citizen'?(app.profile.name||'Ananya Rao'):(app.staffUser||''),'x-debrix-access':JSON.stringify({bookings:access})}});if(!response.ok){let data={};try{data=await response.json()}catch{}throw new Error(data.error||'Evidence could not be opened.')}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=fileName||'booking-evidence';a.target='_blank';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){toast(e.message,true)}}
function bindEvidenceDownloads(root=document){root.querySelectorAll('[data-evidence-download]').forEach(button=>button.onclick=()=>downloadEvidence(button.dataset.bookingId,button.dataset.evidenceDownload,button.dataset.filename))}
function currentTruck(items=app.summary?.bookings||[]){return items.find(b=>b.status==='in_transit'&&b.location?.latitude!=null)||items.find(b=>b.status==='in_transit')||items.find(b=>b.location?.latitude!=null)||null}
function citizenHome(){const bs=app.summary?.bookings||[],active=activeBookings(bs),recent=bs[0],truck=currentTruck(bs),recovery=bs.filter(b=>b.verified_at).reduce((s,b)=>s+Number(b.recycled_tonnes||0)+Number(b.reused_tonnes||0),0);document.querySelector('#view').innerHTML=`${heading('Circular materials, made simple','Arrange a C&D pickup, follow its journey and find recovered materials.')}<section class="hero-card"><div class="hero-copy"><p class="hero-kicker">A simpler way to move debris into use</p><h2>Give construction materials<br>another useful life.</h2><p>Request a pickup, keep the collection trail together, and browse recycled products from participating facilities.</p><div class="hero-actions"><button class="button light" id="start-booking">Book a pickup <span>→</span></button><button class="button outline-light" id="shop-materials">Browse materials</button></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="material-cube cube-one">C&D</div><div class="material-cube cube-two">↻</div><div class="hero-leaf">↗</div></div></section><div class="metric-grid">${metric('Open requests',active.length,n(active.reduce((x,b)=>x+Number(b.quantity_tonnes||0),0),1)+' t in the pickup chain','↗')}${metric('Recovered from your requests',n(recovery,2)+' t','Recorded by a facility with an evidence reference','↻')}${metric('Materials available',app.products.filter(p=>p.available!==false&&Number(p.inventory_tonnes)>0).length,'Offers from participating facilities','◈')}${metric('Latest update',recent?names[recent.status]:'No bookings yet',recent?`${h(recent.id)} · ${time(recent.updated_at||recent.created_at)}`:'Start with a pickup request','·')}</div><div class="grid two home-grid"><div class="home-stack"><section class="card">${cardTitle('Your latest booking','Status and chain-of-custody updates',`<button class="text-link" data-goto="pickups">All bookings →</button>`)}<div class="card-body">${recent?bookingSummary(recent,true):empty('No bookings yet','Your pickup requests and their progress will appear here.','Book a pickup','book')}</div></section>${mapCard({lat:truck?.location?.latitude,lon:truck?.location?.longitude,title:truck?`Truck for ${truck.id}`:'Pickup map',updated:truck?.location?.updated_at,demo:truck?.demo,emptyNote:'No live truck location is being shared. Set your pickup pin while booking.'})}</div><div class="home-stack"><section class="card guidance-card"><div class="card-head"><div><p class="eyebrow">PICKUP PREPARATION</p><h2 class="card-title">A clear site helps collection</h2><p class="card-subtitle">A few checks before the vehicle arrives.</p></div></div><div class="card-body"><ul class="guidance-list"><li>Keep different waste types separated where practical.</li><li>Make sure the collection team can reach the loading point.</li><li>Keep the booking reference and access notes ready.</li><li>Share truck GPS only with the operator’s explicit device permission.</li></ul><p class="source-line">The location pin is a pickup aid. The operator confirms vehicle and collection timing.</p></div></section><section class="card material-callout"><div class="callout-icon">↻</div><div><p class="eyebrow">CIRCULAR MATERIALS</p><h2>Find material with a documented trail</h2><p>Compare product type, listed stock, intended uses and quality evidence before placing a request.</p><button class="button secondary" id="browse-products">Open materials market</button></div></section></div></div>`;bindHomeActions()}
function bindHomeActions(){document.querySelector('#start-booking')?.addEventListener('click',()=>go('book'));document.querySelector('#shop-materials')?.addEventListener('click',()=>go('market'));document.querySelector('#browse-products')?.addEventListener('click',()=>go('market'));document.querySelectorAll('[data-goto]').forEach(x=>x.onclick=()=>go(x.dataset.goto));}
function empty(title,copy,cta='',page=''){return `<div class="empty-state"><div class="empty-illustration">＋</div><b>${h(title)}</b><p>${h(copy)}</p>${cta?`<button class="button secondary" data-goto="${page}">${h(cta)}</button>`:''}</div>`}
function bookingSummary(b,details=false){return `<article class="booking-summary"><div class="booking-main"><div><div class="ref-line"><strong>${h(b.id)}</strong>${demoTag(b.demo)}</div><h3>${h(b.waste_type)} · ${n(b.quantity_tonnes)} t</h3><p>${h(b.locality)} · pickup requested ${date(b.scheduled_date||b.preferred_date)}</p></div><span class="status-pill ${statusClass(b.status)}">${h(names[b.status]||b.status)}</span></div>${flow(b.status)}${details?`<div class="booking-bottom"><span>${b.location?.updated_at?`Truck location updated ${time(b.location.updated_at)}`:'Updates refresh automatically while this page is open.'}</span><button class="button small secondary" data-detail="${h(b.id)}">View journey</button></div>`:''}</article>`}
function citizenBookings(){const bs=app.summary?.bookings||[];document.querySelector('#view').innerHTML=`${heading('My bookings','Follow collection, facility receipt and recovery records.')}<div class="section-toolbar"><div class="segmented"><button class="filter-tab active" data-filter="all">All (${bs.length})</button><button class="filter-tab" data-filter="active">In progress (${activeBookings(bs).length})</button><button class="filter-tab" data-filter="complete">Completed (${bs.filter(b=>['recovered','closed','rejected'].includes(b.status)).length})</button></div><button class="button primary" id="new-pickup">＋ Book a pickup</button></div><div id="booking-list" class="booking-list">${bs.length?bs.map(b=>bookingSummary(b,true)).join(''):empty('No bookings to show','Make a pickup request to start a visible chain of custody.','Book a pickup','book')}</div>`;document.querySelector('#new-pickup').onclick=()=>go('book');document.querySelectorAll('.filter-tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.filter-tab').forEach(x=>x.classList.toggle('active',x===t));const data=t.dataset.filter==='active'?activeBookings(bs):t.dataset.filter==='complete'?bs.filter(b=>['recovered','closed','rejected'].includes(b.status)):bs;document.querySelector('#booking-list').innerHTML=data.length?data.map(b=>bookingSummary(b,true)).join(''):empty('Nothing in this filter','Your other bookings remain available in All.');bindDetails()});bindDetails()}
function bindDetails(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openBooking(b.dataset.detail));bindEvidenceDownloads()}
function bookingPage(){document.querySelector('#view').innerHTML=`${heading('Book a C&D pickup','Share the material, exact pickup pin and preferred date. The operator sees your request as soon as it is saved.')}<div class="form-layout"><form id="booking-form" class="card form-card"><div class="form-step"><span>01</span><div><h2>Pickup details</h2><p>Give the operator enough information to plan a suitable collection.</p></div></div><div class="form-grid"><div class="field"><label for="citizen-name">Your name *</label><input id="citizen-name" name="citizen_name" required maxlength="100" value="${h(app.profile.name)}" autocomplete="name"></div><div class="field"><label for="phone">Phone number *</label><input id="phone" name="phone" required inputmode="tel" maxlength="20" value="${h(app.profile.phone||'')}" placeholder="For pickup coordination" autocomplete="tel"></div><div class="field"><label for="waste-type">Main material *</label><select id="waste-type" name="waste_type" required>${wasteTypes.map(x=>`<option>${h(x)}</option>`).join('')}</select></div><div class="field"><label for="quantity">Estimated load (tonnes) *</label><input id="quantity" name="quantity_tonnes" type="number" min="0.1" max="40" step="0.1" value="1.0" required><small>Give an estimate. Facility weighment is recorded separately.</small></div><div class="field"><label for="date">Preferred pickup date *</label><input id="date" name="preferred_date" type="date" min="${new Date().toISOString().slice(0,10)}" value="${new Date(Date.now()+86400000).toISOString().slice(0,10)}" required></div><div class="field"><label for="locality">Locality *</label><input id="locality" name="locality" maxlength="80" required value="${h(app.profile.locality||'')}" placeholder="e.g. HSR Layout"></div><div class="field full"><label for="address">Pickup address *</label><textarea id="address" name="address" maxlength="250" required placeholder="Building / road / nearby landmark"></textarea></div><div class="field full"><label for="instructions">Access and segregation notes</label><textarea id="instructions" name="instructions" maxlength="500" placeholder="Access restrictions, separated materials, loading point or special handling notes"></textarea></div></div><div class="field"><label>Pickup location pin <span class="required">Required</span></label><div class="location-actions"><button type="button" class="button secondary" id="locate-pickup">⌖ Use this device location</button><span id="pickup-pin-state">Choose the pickup point on the map</span></div><div id="pickup-map">${mapCard({lat:app.profile.latitude,lon:app.profile.longitude,title:"Pickup location",selectable:true})}</div><input type="hidden" name="latitude" value="${h(app.profile.latitude??"")}"><input type="hidden" name="longitude" value="${h(app.profile.longitude??"")}"><small>Click the map or drag the pin to set the exact pickup point. Browser asks permission before reading device location.</small></div><div class="notice subtle"><strong>Before submitting</strong><p>Keep hazardous or non-C&D materials separate and follow applicable local collection instructions. The operator will confirm vehicle assignment and pickup timing.</p></div><div class="form-error" id="booking-error" role="alert"></div><div class="form-actions"><button class="button primary" data-submit>Submit pickup request <span>→</span></button><span class="helper">Tracking access stays in this browser. Keep this device to follow the request.</span></div></form><aside class="form-side"><section class="card side-info"><div class="step-number">02</div><h3>Watch the journey</h3><p>Your request appears in the admin dispatch queue. You can follow assignment, pickup, truck location when shared, facility weighment and final recovery.</p><div class="mini-flow"><span>Request</span><i>→</i><span>Pickup</span><i>→</i><span>Recovery</span></div></section><section class="card side-info"><div class="step-number">03</div><h3>See the material return</h3><p>When a facility records a balanced outcome, your booking shows the material types recovered, evidence reference and any residual destination.</p></section><section class="card side-info small-guide"><p class="eyebrow">LOCATION PRIVACY</p><p>The pickup pin is required to route collection. Truck GPS is separate and only shared when an operator starts location sharing on their device.</p></section></aside></div>`;document.querySelector('#booking-form').addEventListener('submit',submitBooking);document.querySelector('#locate-pickup').onclick=()=>locatePickup();}
function locatePickup(){const state=document.querySelector('#pickup-pin-state');if(!navigator.geolocation){state.textContent='This browser does not support device location. Set a pin by clicking the map.';return}state.textContent='Waiting for location permission…';navigator.geolocation.getCurrentPosition(pos=>{const lat=pos.coords.latitude,lon=pos.coords.longitude;saveProfile({locality:document.querySelector('[name="locality"]').value});document.querySelector('#pickup-map').innerHTML=mapCard({lat,lon,title:'Pickup location',selectable:true});initMapWidgets(document.querySelector('#pickup-map'));syncPickupPin(lat,lon)},err=>{state.textContent=err.code===1?'Location permission was declined. Click the map to set a pin.':'Could not get the location. Try again or click the map to set a pin.'},{enableHighAccuracy:true,timeout:15000,maximumAge:30000})}
async function submitBooking(e){e.preventDefault();const form=e.currentTarget,d=Object.fromEntries(new FormData(form));d.quantity_tonnes=Number(d.quantity_tonnes);d.latitude=d.latitude?Number(d.latitude):null;d.longitude=d.longitude?Number(d.longitude):null;d.instructions=d.instructions.trim();const err=document.querySelector('#booking-error');err.textContent='';if(!Number.isFinite(d.latitude)||!Number.isFinite(d.longitude)){err.textContent='Choose the exact pickup point on the map or use device location before submitting.';document.querySelector('#pickup-map')?.scrollIntoView({behavior:'smooth',block:'center'});return}setBusy(true);try{saveProfile({name:d.citizen_name,phone:d.phone,locality:d.locality});const result=await api('/api/bookings',{method:'POST',body:d});rememberAccess('bookings',result.item.id,result.access_token);toast(`Pickup request ${result.item.id} is in the shared operator queue.`);app.page='pickups';await reload()}catch(x){err.textContent=x.message}finally{setBusy(false)}}
function marketPage(){const products=app.products.filter(p=>p.available!==false&&Number(p.inventory_tonnes)>0);document.querySelector('#view').innerHTML=`${heading('Recycled materials market','Browse products listed by participating processing facilities. Request a quote or availability check—payments are not processed here.')}<div class="notice subtle market-note"><strong>Read product evidence before you buy.</strong> Intended uses are indicative; check the batch test report, applicable standard, project specification and design approval for your application.</div><div class="product-grid">${products.length?products.map(productCard).join(''):empty('No products listed yet','A recycler can publish available stock from the secured administrator portal.')}</div><section class="card buyer-orders">${cardTitle('Your product requests','Track facility confirmation and delivery',`<span class="capture-pill">${app.orders.length} requests</span>`)}<div class="card-body">${app.orders.length?`<div class="order-list">${app.orders.map(orderCard).join('')}</div>`:empty('No product requests','When you request a recycled product, it will appear here.')}</div></section>`;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>requestProduct(b.dataset.buy));document.querySelectorAll('[data-order-inuse]').forEach(b=>b.onclick=()=>updateOrder(b.dataset.orderInuse,'in_use'))}
function productCard(p){const quality=p.quality_status==='tested'?'Test evidence recorded':'Quality evidence not attached',adminInventory=app.mode==='admin'&&app.role==='recycler'&&app.page==='inventory';return `<article class="card product-card"><div class="product-art ${h(p.tint||'sage')}"><span>${h(p.symbol||'◈')}</span>${demoTag(p.demo)}</div><div class="product-copy"><div class="product-meta"><span>${h(p.material_type||'C&D recovered')}</span><span>${n(p.inventory_tonnes,1)} t listed</span></div><h2>${h(p.name)}</h2><p>${h(p.description||'Recovered material from construction and demolition waste.')}</p><div class="quality-note ${p.quality_status==='tested'?'good':''}"><span>◎</span><div><strong>${h(quality)}</strong><small>${h(p.quality_note||'Ask the facility for application-specific test results.')}</small></div></div>${adminInventory?`<form class="stock-edit" data-stock-form="${h(p.id)}"><label>Current stock · tonnes<input name="inventory_tonnes" type="number" min="0" step="0.1" value="${Number(p.inventory_tonnes)}" required></label><button class="button small secondary">Update stock</button></form>`:`<div class="product-footer"><span>${h(p.facility_name||'Participating facility')}</span><button class="button secondary" data-buy="${h(p.id)}">Request product</button></div>`}</div></article>`}
function requestProduct(id){const p=app.products.find(x=>x.id===id);if(!p)return;const c=document.querySelector('#dialog-content');c.innerHTML=`<p class="eyebrow">MATERIALS MARKET</p><h2 class="dialog-title">Request ${h(p.name)}</h2><p class="dialog-meta">${n(p.inventory_tonnes,1)} t listed · ${h(p.facility_name||'Participating facility')}</p><form id="order-form" class="dialog-section form-grid"><input type="hidden" name="product_id" value="${h(p.id)}"><div class="field"><label>Your name *</label><input name="citizen_name" value="${h(app.profile.name)}" required maxlength="100"></div><div class="field"><label>Phone number *</label><input name="phone" value="${h(app.profile.phone||'')}" required maxlength="20"></div><div class="field"><label>Requested quantity (t) *</label><input name="quantity_tonnes" type="number" min="0.1" max="${Number(p.inventory_tonnes)}" step="0.1" value="0.5" required></div><div class="field full"><label>Planned use</label><input name="intended_use" maxlength="180" placeholder="e.g. pedestrian paving—confirm with project designer"></div><label class="checkline full"><input name="member_opt_in" type="checkbox" value="true"><span>Allow the recycler to see my name and order as an active buyer if I later mark the product in use.</span></label><div class="notice subtle full"><strong>Request only.</strong> The facility must confirm stock, specification, price, delivery terms and quality documents directly. No payment is taken in this prototype.</div><div class="form-error full" id="order-error" role="alert"></div><div class="form-actions full"><button class="button primary" data-submit>Send request</button></div></form>`;document.querySelector('#order-form').onsubmit=submitOrder;document.querySelector('#detail-dialog').showModal()}
async function submitOrder(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.quantity_tonnes=Number(d.quantity_tonnes);d.member_opt_in=d.member_opt_in==='true';saveProfile({name:d.citizen_name,phone:d.phone});try{const result=await api('/api/orders',{method:'POST',body:d});rememberAccess('orders',result.item.id,result.access_token);document.querySelector('#detail-dialog').close();toast('Request sent to the recycler.');await reload()}catch(x){document.querySelector('#order-error').textContent=x.message}}
function orderCard(o){return `<article class="order-card"><div><div class="ref-line"><strong>${h(o.id)}</strong>${demoTag(o.demo)}</div><h3>${h(o.product_name)} · ${n(o.quantity_tonnes)} t</h3><p>${h(o.facility_name||'Facility')} · requested ${time(o.created_at)}</p><small>${o.intended_use?h(o.intended_use):'Use not provided'}${o.member_opt_in?' · buyer visibility allowed':''}</small></div><div class="order-status"><span class="status-pill ${o.status==='in_use'?'recovered':''}">${h(orderStatus(o.status))}</span>${o.status==='delivered'?`<button class="button small secondary" data-order-inuse="${h(o.id)}">Mark in use</button>`:''}</div></article>`}
function orderStatus(s){return ({requested:'Request sent',confirmed:'Facility confirmed',delivered:'Delivered',in_use:'In use',cancelled:'Cancelled'})[s]||s}
async function updateOrder(id,status){try{await api(`/api/orders/${encodeURIComponent(id)}`,{method:'PATCH',body:{status}});toast(status==='in_use'?'Marked in use. The recycler sees this only if you opted in.':'Order updated.');await reload()}catch(e){toast(e.message,true)}}
function adminHome(){if(app.role==='operator')operatorHome();else if(app.role==='transporter')allBookings();else recyclerHome()}
function operatorHome(){const all=app.summary?.bookings||[],active=activeBookings(all),newCount=all.filter(b=>b.status==='requested').length,transit=all.filter(b=>['picked_up','in_transit'].includes(b.status)).length,done=all.filter(b=>['recovered','closed','rejected'].includes(b.status)).length;document.querySelector('#view').innerHTML=`${heading('Operations desk','New citizen requests and active transport, refreshed across devices every few seconds.','ADMIN ACCESS')}<div class="admin-banner"><span class="lock-mark">✓</span><div><strong>Secured administrator session</strong><small>Operator actions are stored in the shared workflow. Seed records carry a DEMO label.</small></div><span class="capture-pill">Last refresh ${app.lastUpdated?time(app.lastUpdated):'—'}</span></div><div class="metric-grid">${metric('Needs assignment',newCount,'Requests waiting in dispatch','＋')}${metric('In field',transit,'Picked up or on the way to facility','↗')}${metric('Completed',done,'Recovery recorded or closed','✓')}${metric('Total material registered',n(all.reduce((s,b)=>s+Number(b.quantity_tonnes||0),0),1)+' t','All visible records · demo included','▤')}</div><div class="grid two home-grid"><section class="card">${cardTitle('Newest citizen requests','Contact, material and pickup detail appear here when submitted',`<button class="text-link" data-goto="bookings">All bookings →</button>`)}<div class="card-body">${newCount?all.filter(b=>b.status==='requested').slice(0,4).map(operatorCard).join(''):empty('Dispatch queue is clear','New citizen requests will appear here as soon as they are submitted.')}</div></section><div class="home-stack"><section class="card">${cardTitle('Loads in transit','Device location appears after an operator opts in to GPS sharing',`<button class="text-link" data-goto="map">Operations map →</button>`)}<div class="card-body">${all.filter(b=>b.status==='in_transit').length?all.filter(b=>b.status==='in_transit').map(b=>miniTruck(b)).join(''):empty('No active truck runs','A truck will appear when an operator marks a load in transit.')}</div></section><section class="card intelligence-card"><h3>Live update interval</h3><p>The operator and citizen screens refresh the shared state every 12 seconds while open. Browser GPS is sent only after the operator starts sharing from an HTTPS device.</p><div class="signal"><strong>Evidence boundary:</strong> A last reported GPS point is not a route prediction or arrival time.</div></section></div></div>`;bindGoto();bindOperatorCards()}
function operatorCard(b){return `<article class="op-card"><div class="op-card-top"><div class="ref-line"><strong>${h(b.id)}</strong>${demoTag(b.demo)}</div><span class="status-pill ${statusClass(b.status)}">${h(names[b.status])}</span></div><h3>${h(b.waste_type)} · ${n(b.quantity_tonnes)} t</h3><div class="detail-grid"><div><small>CITIZEN</small><strong>${h(b.citizen_name)}</strong><a href="tel:${h(b.phone)}">${h(b.phone)}</a></div><div><small>PICKUP</small><strong>${h(b.locality)}</strong><span>${h(b.address)}</span></div><div><small>REQUESTED FOR</small><strong>${date(b.scheduled_date||b.preferred_date)}</strong><span>${h(b.instructions||'No special instructions')}</span></div></div><div class="op-actions">${operatorActions(b)}<button class="button small secondary" data-detail="${h(b.id)}">Full record</button></div></article>`}
function operatorActions(b){if(app.role==='operator'){if(b.status==='requested')return '<button class="button small primary" data-assign="'+h(b.id)+'">Assign pickup</button><button class="button small danger" data-reject="'+h(b.id)+'">Reject request</button>';return '<span class="helper">'+(b.status==='assigned'?'Awaiting transporter pickup confirmation.':b.status==='picked_up'?'Awaiting transporter departure update.':b.status==='in_transit'?'Live transport updates are shared by the assigned transporter.':'Next step is recorded by the facility.')+'</span>'}if(app.role==='transporter'){if(b.status==='assigned')return '<button class="button small primary" data-status="'+h(b.id)+'" data-next="picked_up">Confirm pickup</button>';if(b.status==='picked_up')return '<button class="button small primary" data-status="'+h(b.id)+'" data-next="in_transit">Start transit</button>';if(b.status==='in_transit')return '<button class="button small secondary" data-gps="'+h(b.id)+'">'+(app.watchId&&app.selectedBooking===b.id?'Stop GPS sharing':'Share live GPS')+'</button>'}return '<span class="helper">Next step is recorded by the facility.</span>'} function bindOperatorCards(){document.querySelectorAll('[data-assign]').forEach(x=>x.onclick=()=>assignBooking(x.dataset.assign));document.querySelectorAll('[data-reject]').forEach(x=>x.onclick=()=>rejectBooking(x.dataset.reject));document.querySelectorAll('[data-status]').forEach(x=>x.onclick=()=>advanceBooking(x.dataset.status,x.dataset.next));document.querySelectorAll('[data-gps]').forEach(x=>x.onclick=()=>toggleGps(x.dataset.gps));bindDetails()}
function allBookings(){const all=app.summary?.bookings||[];document.querySelector('#view').innerHTML=`${heading(app.role==='transporter'?'My assigned jobs':'All bookings',app.role==='transporter'?'Only pickups assigned to your transporter account appear here.':'Search and review live requests, active operations and completed recovery records.','ADMIN ACCESS')}<div class="section-toolbar"><div class="segmented">${['all','active','done'].map((v,i)=>`<button class="filter-tab ${i===0?'active':''}" data-admin-filter="${v}">${['All','In progress','Completed'][i]}</button>`).join('')}</div><label class="search-box"><span>⌕</span><input id="booking-search" placeholder="Search reference, locality or citizen"></label></div><div id="admin-booking-list" class="op-list">${all.length?all.map(operatorCard).join(''):empty('No bookings yet','Citizen pickup requests will appear here.')}</div>`;bindOperatorCards();let filter='all';function apply(){const q=document.querySelector('#booking-search').value.toLowerCase();const data=all.filter(b=>(filter==='active'?activeBookings([b]).length:filter==='done'?['recovered','closed','rejected'].includes(b.status):true)&&[b.id,b.locality,b.citizen_name,b.waste_type].some(x=>String(x||'').toLowerCase().includes(q)));document.querySelector('#admin-booking-list').innerHTML=data.length?data.map(operatorCard).join(''):empty('No matching bookings','Try another status or search phrase.');bindOperatorCards()}document.querySelector('#booking-search').oninput=apply;document.querySelectorAll('[data-admin-filter]').forEach(x=>x.onclick=()=>{filter=x.dataset.adminFilter;document.querySelectorAll('[data-admin-filter]').forEach(t=>t.classList.toggle('active',t===x));apply()})}
function operationsMap(){const all=app.summary?.bookings||[],current=currentTruck(all),gps=all.filter(b=>b.location?.latitude!=null);document.querySelector('#view').innerHTML=`${heading('Operations map','OpenStreetMap basemap with location pins only when a citizen or operator device has shared coordinates.','ADMIN ACCESS')}<div class="grid two"><div>${current?mapCard({lat:current.location?.latitude,lon:current.location?.longitude,title:`Current load · ${current.id}`,updated:current.location?.updated_at,demo:current.demo,emptyNote:'This in-transit booking has not shared GPS yet.'}):mapCard({})}</div><section class="card">${cardTitle('Current operations','Tap a booking to view its last shared GPS point') }<div class="card-body">${all.length?all.filter(b=>!['closed'].includes(b.status)).map(b=>`<button class="map-row" data-map-select="${h(b.id)}"><span class="map-row-icon ${b.location?.latitude!=null?'has-pin':''}">⌖</span><span><strong>${h(b.id)} · ${h(b.locality)}</strong><small>${h(names[b.status])} · ${b.location?.updated_at?`GPS ${time(b.location.updated_at)}`:'No GPS point reported'}</small></span><span class="status-pill ${statusClass(b.status)}">${h(b.status==='in_transit'?'On route':names[b.status])}</span></button>`).join(''):empty('No operations to map','Bookings appear once citizens submit requests.')}</div></section></div><p class="map-disclaimer">Map tiles © OpenStreetMap contributors. Pins represent reported device coordinates or an explicitly selected pickup point; demo records are labelled. No route or ETA is estimated.</p>`;document.querySelectorAll('[data-map-select]').forEach(x=>x.onclick=()=>{const b=all.find(b=>b.id===x.dataset.mapSelect);if(b)openBooking(b.id)})}
function miniTruck(b){return `<button class="truck-row" data-detail="${h(b.id)}"><span class="truck-icon">↗</span><span><strong>${h(b.id)} · ${h(b.locality)}</strong><small>${h(b.vehicle_id||'Vehicle not assigned')} · ${b.location?.updated_at?`GPS updated ${time(b.location.updated_at)}`:'No device location yet'}</small></span><span class="status-pill transit">In transit</span></button>`}
function recyclerHome(){const all=app.summary?.bookings||[],incoming=all.filter(b=>b.status==='in_transit').length,processing=all.filter(b=>b.status==='processing').length,recovered=all.filter(b=>['recovered','closed','rejected'].includes(b.status)),recycled=all.reduce((s,b)=>s+Number(b.recycled_tonnes||0),0),reused=all.reduce((s,b)=>s+Number(b.reused_tonnes||0),0),residual=all.reduce((s,b)=>s+Number(b.residual_tonnes||0),0),orders=app.orders.filter(o=>!['cancelled'].includes(o.status));const productOutput={};for(const b of all)for(const o of b.outputs||[])productOutput[o.material_type]=(productOutput[o.material_type]||0)+Number(o.tonnes||0);document.querySelector('#view').innerHTML=`${heading('Facility overview','Track facility receipt, sort-by-material recovery and outgoing recycled products.','ADMIN ACCESS')}<div class="admin-banner"><span class="lock-mark">✓</span><div><strong>Secured recycler workspace</strong><small>Recovery records require a balanced weight split and evidence reference.</small></div><span class="capture-pill">Updated ${app.lastUpdated?time(app.lastUpdated):'—'}</span></div><div class="metric-grid">${metric('Loads awaiting receipt',incoming,'Operator reports in transit','⇣')}${metric('Being processed',processing,'Facility sorting stage','⟳')}${metric('Recycled output',n(recycled,2)+' t','Recorded material products','◈')}${metric('Reusable salvage',n(reused,2)+' t','Kept separate from debris recycling','↻')}</div><div class="grid two home-grid"><section class="card">${cardTitle('Recovered materials by type','From recycler-entered recovery output rows',`<button class="text-link" data-goto="processing">Recovery records →</button>`)}<div class="card-body">${Object.keys(productOutput).length?`<div class="breakdown-list">${Object.entries(productOutput).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="breakdown-row"><span>${h(k)}</span><div class="breakdown-track"><i style="width:${Math.min(100,v/Math.max(1,recycled)*100)}%"></i></div><strong>${n(v,2)} t</strong></div>`).join('')}</div>`:empty('No recovery outputs yet','When loads are weighed and processed, material-specific totals appear here.')}</div></section><div class="home-stack"><section class="card">${cardTitle('Inbound loads','Received when transport handoff is complete') }<div class="card-body">${all.filter(b=>['in_transit','received'].includes(b.status)).slice(0,4).map(recyclerLoadCard).join('')||empty('No inbound loads','In-transit deliveries will appear here.')}</div></section><section class="card">${cardTitle('Product requests','Citizens request available products from their portal',`<button class="text-link" data-goto="buyers">Buyer network →</button>`)}<div class="card-body">${orders.length?orders.slice(0,3).map(orderCardAdmin).join(''):empty('No market requests','New requests appear here after a citizen chooses a product.')}</div></section></div></div><div class="notice subtle"><strong>Mass balance summary:</strong> ${n(recycled,2)} t recycled + ${n(reused,2)} t reused + ${n(residual,2)} t residual. Includes DEMO-tagged seed records. Facility data is user-entered and not independently audited.</div>`;bindGoto();bindRecyclerActions()}
function recyclerLoadCard(b){return `<article class="load-card"><div class="load-card-header"><strong>${h(b.id)} ${demoTag(b.demo)}</strong><span class="status-pill ${statusClass(b.status)}">${h(names[b.status])}</span></div><p>${h(b.citizen_name)} · ${h(b.waste_type)} · ${n(b.quantity_tonnes)} t registered</p><small>${h(b.address)} · ${h(b.operator_name||'Operator pending')} · ${h(b.vehicle_id||'Vehicle pending')}</small><div class="op-actions"><button class="button small secondary" data-detail="${h(b.id)}">Journey</button>${b.status==='in_transit'?`<button class="button small primary" data-receive="${h(b.id)}">Receive load</button>`:''}${b.status==='received'?`<button class="button small primary" data-start-process="${h(b.id)}">Start processing</button>`:''}</div></article>`}
function intakePage(){const all=app.summary?.bookings||[],loads=all.filter(b=>['in_transit','received'].includes(b.status));document.querySelector('#view').innerHTML=`${heading('Incoming loads','Match each arrival to its booking, measured weighbridge weight and handoff evidence.','ADMIN ACCESS')}<div class="notice subtle"><strong>Receipt check:</strong> compare registered estimate with actual facility weight; record the ticket reference and flag discrepancies before processing.</div><div class="op-list">${loads.length?loads.map(recyclerLoadCard).join(''):empty('No incoming loads','When an operator marks a pickup in transit, it appears here.')}</div>`;bindRecyclerActions()}
function processingPage(){const all=app.summary?.bookings||[],loads=all.filter(b=>['received','processing','recovered','closed'].includes(b.status));document.querySelector('#view').innerHTML=`${heading('Processing and recovery','Record the measured output streams separately. The total must reconcile to facility receipt.','ADMIN ACCESS')}<div class="metric-grid">${metric('Received',n(all.reduce((s,b)=>s+Number(b.received_tonnes||0),0),2)+' t','Facility weighments','⇣')}${metric('Recycled',n(all.reduce((s,b)=>s+Number(b.recycled_tonnes||0),0),2)+' t','Mineral C&D products','◈')}${metric('Reused',n(all.reduce((s,b)=>s+Number(b.reused_tonnes||0),0),2)+' t','Salvage / direct reuse','↻')}${metric('Residual',n(all.reduce((s,b)=>s+Number(b.residual_tonnes||0),0),2)+' t','Destination required','·')}</div><div class="op-list">${loads.length?loads.map(b=>processingCard(b)).join(''):empty('No facility records','Loads appear after facility receipt.')}</div>`;bindRecyclerActions()}
function processingCard(b){const hasReceipt=Number(b.received_tonnes)>0;return `<article class="op-card"><div class="op-card-top"><div><div class="ref-line"><strong>${h(b.id)}</strong>${demoTag(b.demo)}</div><h3>${h(b.waste_type)} · ${hasReceipt?`${n(b.received_tonnes)} t received`:`${n(b.quantity_tonnes)} t estimated · receipt not recorded`}</h3></div><span class="status-pill ${statusClass(b.status)}">${h(names[b.status])}</span></div><div class="detail-grid"><div><small>SOURCE</small><strong>${h(b.locality)}</strong><span>${h(b.citizen_name)}</span></div><div><small>FACILITY TICKET</small><strong>${h(b.facility_id||'—')}</strong><span>${h(b.receipt_evidence||'Evidence not recorded')}</span></div><div><small>PROCESSING RECORD</small><strong>${b.verified_at?time(b.verified_at):'Not recorded'}</strong><span>${h(b.sort_notes||'Awaiting sorting entry')}</span></div></div>${evidenceList(b)}${b.verified_at?`<div class="outcome-list">${(b.outputs||[]).map(o=>`<span class="outcome-chip">${h(o.material_type)} · ${n(o.tonnes,2)} t</span>`).join('')||'<span class="outcome-chip">Legacy record · output types not itemised</span>'}<span class="outcome-chip">Reuse · ${n(b.reused_tonnes,2)} t</span><span class="outcome-chip">Residual · ${n(b.residual_tonnes,2)} t</span></div>`:''}<div class="op-actions"><button class="button small secondary" data-detail="${h(b.id)}">Chain of custody</button>${b.status==='received'?`<button class="button small primary" data-start-process="${h(b.id)}">Start processing</button>`:''}${b.status==='processing'&&hasReceipt?`<button class="button small primary" data-process="${h(b.id)}">Record material outputs</button>`:''}${b.status==='processing'&&!hasReceipt?'<span class="helper">Legacy DEMO status has no measured receipt; record a real receipt before completing recovery.</span>':''}${b.status==='recovered'?`<button class="button small primary" data-complete="${h(b.id)}">Complete booking</button>`:''}${b.status==='closed'?'<span class="helper">Booking complete · recovery evidence remains available.</span>':''}</div></article>`}
function bindRecyclerActions(){document.querySelectorAll('[data-receive]').forEach(x=>x.onclick=()=>receiveLoad(x.dataset.receive));document.querySelectorAll('[data-start-process]').forEach(x=>x.onclick=()=>startProcessing(x.dataset.startProcess));document.querySelectorAll('[data-process]').forEach(x=>x.onclick=()=>recordProcessing(x.dataset.process));document.querySelectorAll('[data-complete]').forEach(x=>x.onclick=()=>advanceBooking(x.dataset.complete,'closed'));document.querySelectorAll('[data-detail]').forEach(x=>x.onclick=()=>openBooking(x.dataset.detail));document.querySelectorAll('[data-order-action]').forEach(x=>x.onclick=()=>updateOrder(x.dataset.id,x.dataset.orderAction));bindEvidenceDownloads()}
function receiveLoad(id){const b=app.summary.bookings.find(x=>x.id===id);dialogForm('FACILITY RECEIPT','Receive '+id,'Registered estimate '+n(b.quantity_tonnes)+' t · '+h(b.locality),'<div class="form-grid"><div class="field"><label>Assigned facility ID *</label><input name="facility_id" required value="'+h(b.facility_id||'')+'" maxlength="60"></div><div class="field"><label>Assigned facility name *</label><input name="facility_name" required value="'+h(b.facility_name||'')+'" maxlength="100"></div><div class="field"><label>Measured received weight (t) *</label><input name="received_tonnes" type="number" min="0.01" max="'+(b.quantity_tonnes*1.15).toFixed(2)+'" step="0.01" value="'+Number(b.quantity_tonnes).toFixed(2)+'" required></div><div class="field"><label>Weighbridge / evidence reference *</label><input name="evidence_ref" required maxlength="180" placeholder="Ticket or register reference"></div><div class="field full"><label>Weight discrepancy note <span class="optional">Required above 5% variance</span></label><textarea name="discrepancy_note" maxlength="240" rows="2" placeholder="Explain estimate differences when applicable"></textarea></div><div class="field full"><label>Attach weighbridge ticket <span class="optional">Optional</span></label><input name="evidence_file" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,application/pdf,image/jpeg,image/png,image/webp"><small>Private upload · PDF or image · maximum 2 MB.</small></div></div>','Record receipt',async d=>{d.received_tonnes=Number(d.received_tonnes);await api('/api/bookings/'+encodeURIComponent(id)+'/receipt',{method:'PATCH',body:d})})} async function startProcessing(id){try{await api(`/api/bookings/${encodeURIComponent(id)}/status`,{method:'PATCH',body:{status:'processing',facility_name:'Bengaluru C&D Facility'}});toast(`Processing started for ${id}.`);await reload()}catch(e){toast(e.message,true)}}
function recordProcessing(id){const b=app.summary.bookings.find(x=>x.id===id),received=Number(b.received_tonnes);dialogForm('SORTING & MATERIAL RECOVERY',`Record outputs · ${id}`,`Received ${n(received,2)} t · enter actual weighments; do not use a default recovery rate.`,`<div class="field full"><label>Recycled product outputs (one or more types) *</label><div id="output-rows"><div class="output-row"><select name="material_type" required><option value="Recycled concrete aggregate">Recycled concrete aggregate</option><option value="Recycled mixed aggregate">Recycled mixed aggregate</option><option value="Fine aggregate / manufactured sand">Fine aggregate / manufactured sand</option><option value="Bricks, blocks or tiles">Bricks, blocks or tiles</option><option value="Pavers or kerbs">Pavers or kerbs</option><option value="Manufactured soil">Manufactured soil</option><option value="Other tested product">Other tested product</option></select><input name="output_tonnes" type="number" min="0" step="0.01" placeholder="tonnes" required><button type="button" class="remove-output" aria-label="Remove output">×</button></div></div><button type="button" class="button small secondary" id="add-output">＋ Add a material type</button></div><div class="field"><label>Direct reuse / salvage (t) *</label><input name="reused_tonnes" type="number" min="0" step="0.01" value="0" required></div><div class="field"><label>Residual / reject (t) *</label><input name="residual_tonnes" type="number" min="0" step="0.01" value="0" required></div><div class="field full"><label>Residual destination <span class="optional">Required when residual &gt; 0</span></label><input name="residual_destination" maxlength="180" placeholder="Record authorised / appropriate destination"></div><div class="field full"><label>Sorting and quality notes</label><textarea name="sort_notes" maxlength="500" placeholder="Separation, contamination checks, grading or test report summary"></textarea></div><div class="field full"><label>Evidence reference *</label><input name="evidence_ref" required maxlength="180" placeholder="Weighbridge ticket, batch record or test report reference"></div><div class="field full"><label>Attach processing evidence <span class="optional">Optional</span></label><input name="evidence_file" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,application/pdf,image/jpeg,image/png,image/webp"><small>Private upload · PDF or image · maximum 2 MB.</small></div><input name="facility_name" type="hidden" value="Bengaluru C&D Facility"><p class="helper full">Recycled outputs + reuse + residual must balance the received weight within 0.03 t. Evidence entry is not an independent audit.</p>`,`Save recovery record`,async d=>{const form=document.querySelector('#dialog-form');d.outputs=[...form.querySelectorAll('.output-row')].map(row=>({material_type:row.querySelector('[name=material_type]').value,tonnes:Number(row.querySelector('[name=output_tonnes]').value)}));d.recycled_tonnes=d.outputs.reduce((s,x)=>s+x.tonnes,0);d.reused_tonnes=Number(d.reused_tonnes||0);d.residual_tonnes=Number(d.residual_tonnes||0);await api(`/api/bookings/${encodeURIComponent(id)}/processing`,{method:'PATCH',body:d})});document.querySelector('#add-output').onclick=()=>{const row=document.createElement('div');row.className='output-row';row.innerHTML='<select name="material_type"><option>Recycled concrete aggregate</option><option>Recycled mixed aggregate</option><option>Fine aggregate / manufactured sand</option><option>Bricks, blocks or tiles</option><option>Pavers or kerbs</option><option>Manufactured soil</option><option>Other tested product</option></select><input name="output_tonnes" type="number" min="0" step="0.01" placeholder="tonnes" required><button type="button" class="remove-output" aria-label="Remove output">×</button>';document.querySelector('#output-rows').append(row);row.querySelector('.remove-output').onclick=()=>row.remove()};document.querySelectorAll('.remove-output').forEach(x=>x.onclick=()=>x.closest('.output-row').remove())}
async function encodeEvidenceFile(file){if(!file||!file.size)return null;if(file.size>2097152)throw new Error('Evidence files must be 2 MB or smaller.');const ext=String(file.name||'').toLowerCase().split('.').pop(),types={pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp'},type=file.type||types[ext];if(!Object.values(types).includes(type))throw new Error('Attach a PDF, JPG, PNG or WebP evidence file.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return{name:file.name,type,data:btoa(binary)}}
function dialogForm(eyebrow,title,sub,fields,submit,callback){document.querySelector('#dialog-content').innerHTML=`<p class="eyebrow">${h(eyebrow)}</p><h2 class="dialog-title">${h(title)}</h2><p class="dialog-meta">${sub}</p><form id="dialog-form" class="dialog-section form-grid">${fields}<div class="form-error full" id="dialog-error" role="alert"></div><div class="form-actions full"><button class="button primary" data-submit>${h(submit)}</button></div></form>`;document.querySelector('#dialog-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{if(typeof File!=='undefined'&&d.evidence_file instanceof File){d.evidence_file=await encodeEvidenceFile(d.evidence_file)}else delete d.evidence_file;setBusy(true);await callback(d);document.querySelector('#detail-dialog').close();toast('Tracking access stays in this browser. Keep this device to follow the request.');await reload()}catch(x){document.querySelector('#dialog-error').textContent=x.message}finally{setBusy(false)}};document.querySelector('#detail-dialog').showModal()}
function inventoryPage(){const products=app.products;document.querySelector('#view').innerHTML=`${heading('Product inventory','List recovered materials available to citizens and update stock as batches change.','ADMIN ACCESS')}<section class="card inventory-form-card">${cardTitle('Publish a product batch','Offers are requests for availability, not in-app sales or payments')}<form id="product-form" class="card-body form-grid"><div class="field"><label>Product name *</label><input name="name" required maxlength="120" placeholder="e.g. 10–20 mm recycled aggregate"></div><div class="field"><label>Material type *</label><select name="material_type"><option>Recycled concrete aggregate</option><option>Recycled mixed aggregate</option><option>Fine aggregate / manufactured sand</option><option>Bricks, blocks or tiles</option><option>Pavers or kerbs</option><option>Manufactured soil</option><option>Recovered steel / metal</option><option>Salvaged timber</option></select></div><div class="field"><label>Available stock (tonnes) *</label><input name="inventory_tonnes" type="number" min="0.1" step="0.1" required></div><div class="field"><label>Facility name *</label><input name="facility_name" maxlength="100" value="Bengaluru C&D Facility" required></div><div class="field full"><label>Product description</label><input name="description" maxlength="400" placeholder="Feedstock, grading or product dimensions"></div><div class="field full"><label>Quality evidence and application notes</label><textarea name="quality_note" maxlength="500" placeholder="Attach/identify the applicable test report and clearly state its scope"></textarea></div><div class="form-actions full"><button class="button primary" data-submit>Publish product</button></div></form></section><div class="product-grid admin-products">${products.length?products.map(productCard).join(''):empty('No product offers','Publish stock above to show recovered materials in the citizen market.')}</div>`;document.querySelector('#product-form').onsubmit=publishProduct;document.querySelectorAll('[data-stock-form]').forEach(form=>form.onsubmit=updateProductStock)}
async function publishProduct(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.inventory_tonnes=Number(d.inventory_tonnes);try{setBusy(true);await api('/api/products',{method:'POST',body:d});toast('Product offer published to the citizen market.');await reload()}catch(x){toast(x.message,true)}finally{setBusy(false)}}
async function updateProductStock(e){e.preventDefault();const productId=e.currentTarget.dataset.stockForm,d=Object.fromEntries(new FormData(e.currentTarget));d.inventory_tonnes=Number(d.inventory_tonnes);try{await api(`/api/products/${encodeURIComponent(productId)}`,{method:'PATCH',body:d});toast('Product stock updated.');await reload()}catch(x){toast(x.message,true)}}
function buyersPage(){const orders=app.orders.filter(o=>o.status!=='cancelled'),members=orders.filter(o=>o.status==='in_use'&&o.member_opt_in);document.querySelector('#view').innerHTML=`${heading('Buyer network','Product requests and the active buyer list come from citizen-portal orders and an explicit in-use update.','ADMIN ACCESS')}<div class="metric-grid">${metric('Requests',orders.length,'All active market requests','▤')}${metric('Confirmed / delivered',orders.filter(o=>['confirmed','delivered','in_use'].includes(o.status)).length,'Facility status updates','✓')}${metric('Active members',members.length,'In-use + member visibility consent','◎')}${metric('Ordered quantity',n(orders.reduce((s,o)=>s+Number(o.quantity_tonnes||0),0),1)+' t','Requests are not completed sales','◈')}</div><section class="card buyer-orders">${cardTitle('Product requests','Confirm availability and mark delivery when handoff is complete')}<div class="card-body">${orders.length?`<div class="order-list">${orders.map(orderCardAdmin).join('')}</div>`:empty('No product requests','Citizen requests appear here as soon as they are sent.')}</div></section><section class="card buyer-orders">${cardTitle('Active members','Customers who marked a delivered product as in use and opted in to appear here')}<div class="card-body">${members.length?`<div class="member-list">${members.map(o=>`<article class="member-row"><div class="member-avatar">${h((o.citizen_name||'C')[0])}</div><div><strong>${h(o.citizen_name)}</strong><small>${h(o.product_name)} · ${n(o.quantity_tonnes)} t · ${h(o.intended_use||'Use not specified')}</small></div><span>${demoTag(o.demo)} Active</span></article>`).join('')}</div>`:empty('No opted-in active members yet','A buyer appears after delivery when they mark the product in use and allow visibility.')}</div></section><p class="source-line">Buyer visibility is limited to name, product, quantity and stated use when consent is recorded. Contact details are only used for order fulfilment.</p>`;bindRecyclerActions()}
function orderCardAdmin(o){return `<article class="order-card"><div><div class="ref-line"><strong>${h(o.id)}</strong>${demoTag(o.demo)}</div><h3>${h(o.product_name)} · ${n(o.quantity_tonnes)} t</h3><p>${h(o.citizen_name)} · ${h(o.phone)} · requested ${time(o.created_at)}</p><small>${o.intended_use?h(o.intended_use):'Use not provided'}${o.member_opt_in?' · opted in to active buyer list':' · not opted in to member list'}</small></div><div class="order-status"><span class="status-pill ${o.status==='in_use'?'recovered':''}">${h(orderStatus(o.status))}</span>${o.status==='requested'?`<button class="button small secondary" data-id="${h(o.id)}" data-order-action="confirmed">Confirm</button>`:''}${o.status==='confirmed'?`<button class="button small primary" data-id="${h(o.id)}" data-order-action="delivered">Mark delivered</button>`:''}</div></article>`}
function guidePage(){document.querySelector('#view').innerHTML=`${heading('C&D material guide','Recovery routes and product uses grounded in Indian government and standards sources. Every application is conditional on quality, testing, design and local approval.')}<div class="notice subtle guide-law"><strong>Regulatory context · India, checked 23 Oct 2026.</strong> The Environment (Construction and Demolition) Waste Management Rules, 2025 took effect on 1 Apr 2026. The rules distinguish debris-derived products from resalable/reusable streams, require quality compliance for recycled products and specify phased utilisation targets. This prototype is not the CPCB portal and does not certify legal compliance. <a href="https://cpcb.gov.in/uploads/hwmd/C%26D_rules_2025.pdf" target="_blank" rel="noreferrer">Read the official rules ↗</a></div><div class="guide-grid">${materials.map((m,i)=>`<article class="card guide-card"><span class="guide-index">${String(i+1).padStart(2,'0')}</span><span class="guide-type">${h(m.type)}</span><h2>${h(m.name)}</h2><div><strong>Recovery route</strong><p>${h(m.route)}</p></div><div><strong>Potential use</strong><p>${h(m.uses)}</p></div><div class="guide-caution"><strong>Quality / accounting boundary</strong><p>${h(m.caution)}</p></div></article>`).join('')}</div><section class="card regulatory-card">${cardTitle('Indicative phased utilisation targets','Rules 2025 · for qualifying project scopes; verify applicability with local authority')}<div class="card-body"><div class="target-grid"><div><span>Construction & reconstruction</span><strong>5% → 25%</strong><small>2026–27: 5% · 2027–28: 10% · 2028–29: 15% · 2029–30: 20% · 2030–31 onward: 25%</small></div><div><span>Road construction</span><strong>5% → 15%</strong><small>2026–28: 5% · 2028–30: 10% · 2030–31 onward: 15%</small></div></div><p class="source-line">Rules say targets apply to construction activities with built-up area of 20,000 m² or above and road construction; project plans, scope, approvals and technical specifications govern. Do not apply these percentages to an individual household booking.</p></div></section><section class="card sources-card">${cardTitle('Source notes','Official rules, technical guidance and standards register')}<div class="card-body source-links"><a href="https://cpcb.gov.in/uploads/hwmd/C%26D_rules_2025.pdf" target="_blank" rel="noreferrer"><strong>CPCB · Environment (Construction and Demolition) Waste Management Rules, 2025</strong><small>Effective 1 April 2026; schedules list product streams, utilisation and road targets.</small></a><a href="https://mohua.gov.in/upload/uploadfiles/files/Part2.pdf" target="_blank" rel="noreferrer"><strong>MoHUA · C&D waste management manual, processed-waste uses</strong><small>Technical use descriptions; check against newer rules, current standards and project approvals.</small></a><a href="https://cpwd.gov.in/Publication/CPWD_Works_Manual_2022_13122022.pdf" target="_blank" rel="noreferrer"><strong>CPWD Works Manual 2022 · recycled C&D products</strong><small>Use is subject to quality control, relevant standards, specifications and feasibility.</small></a><a href="https://standards.bis.gov.in/website/standard-details" target="_blank" rel="noreferrer"><strong>BIS · Know Your Standard</strong><small>Look up current IS 383 and product-specific standards before claiming a batch complies.</small></a></div></section>`}
function openBooking(id){const b=app.summary.bookings.find(x=>x.id===id);if(!b)return;const outputs=(b.outputs||[]).map(o=>`<div class="recovery-line"><span>${h(o.material_type)}</span><strong>${n(o.tonnes,2)} t</strong></div>`).join('');const lat=b.location?.latitude??b.pickup_latitude,lon=b.location?.longitude??b.pickup_longitude;document.querySelector('#dialog-content').innerHTML=`<p class="eyebrow">DEBRIX · CHAIN OF CUSTODY ${demoTag(b.demo)}</p><h2 class="dialog-title">${h(b.id)} · ${h(b.locality)}</h2><p class="dialog-meta">${h(b.waste_type)} · ${n(b.quantity_tonnes)} t estimated · requested for ${date(b.scheduled_date||b.preferred_date)}</p><div class="dialog-section"><h3>Current status · ${h(names[b.status])}</h3>${flow(b.status)}</div><div class="dialog-section"><h3>Pickup and transport</h3><p>${h(b.citizen_name)} · ${h(b.phone)}<br>${h(b.address)}<br>${h(b.operator_name||'Operator not assigned')} · ${h(b.vehicle_id||'Vehicle not assigned')}</p>${b.location?.latitude!=null?`<p class="source-line">Last device GPS point ${Number(b.location.latitude).toFixed(5)}, ${Number(b.location.longitude).toFixed(5)} · accuracy ±${Math.round(b.location.accuracy_m||0)} m · ${time(b.location.updated_at)}${demoTag(b.location.demo)}</p>`:'<p class="source-line">No live vehicle GPS update has been reported.</p>'}</div>${lat!=null&&lon!=null?`<div class="dialog-section">${mapCard({lat,lon,title:`Location · ${b.id}`,updated:b.location?.updated_at,demo:b.demo})}</div>`:''}<div class="dialog-section"><h3>Material journey</h3>${activity(b)}</div>${evidenceList(b)}${b.verified_at?`<div class="dialog-section"><div class="notice success"><strong>Facility recovery record · ${time(b.verified_at)}</strong><div class="recovery-list">${outputs}<div class="recovery-line"><span>Direct reuse / salvage</span><strong>${n(b.reused_tonnes,2)} t</strong></div><div class="recovery-line"><span>Residual · ${h(b.residual_destination||'destination not recorded')}</span><strong>${n(b.residual_tonnes,2)} t</strong></div></div><p>Evidence reference: ${h(b.evidence_ref||'—')} · facility ${h(b.facility_id||'—')}</p><small>Recorded and balanced in the DEBRIX pilot ledger; independent verification has not been performed.</small></div></div>`:''}`;initMapWidgets(document.querySelector('#dialog-content'));bindEvidenceDownloads();document.querySelector('#detail-dialog').showModal()}
function assignBooking(id){const b=app.summary.bookings.find(x=>x.id===id);dialogForm('DISPATCH ASSIGNMENT','Assign '+id,h(b.citizen_name)+' · '+h(b.waste_type)+' · '+n(b.quantity_tonnes)+' t · '+h(b.address),'<div class="form-grid"><div class="field"><label>Transporter account username *</label><input name="operator_name" required maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9._-]{1,39}" placeholder="Example: driver-01"></div><div class="field"><label>Vehicle registration / ID *</label><input name="vehicle_id" required maxlength="30" placeholder="Enter assigned vehicle"></div><div class="field"><label>Scheduled pickup date *</label><input name="scheduled_date" type="date" value="'+h(b.preferred_date)+'" required></div><div class="field"><label>Destination facility ID *</label><input name="facility_id" required maxlength="60" placeholder="Registered facility ID"></div><div class="field full"><label>Destination facility name *</label><input name="facility_name" required maxlength="100" placeholder="Assigned processing facility"></div><div class="field full"><label>Dispatch note</label><input name="note" maxlength="180" placeholder="Optional note for the citizen"></div></div>','Assign pickup',async d=>api('/api/bookings/'+encodeURIComponent(id)+'/status',{method:'PATCH',body:Object.assign(d,{status:'assigned'})}))}
function rejectBooking(id){dialogForm('REQUEST REVIEW','Reject '+id,'The customer will see this reason in their booking history.','<div class="field full"><label>Reason for rejection *</label><textarea name="note" required maxlength="160" rows="3" placeholder="Explain why the pickup cannot be accepted"></textarea></div>','Reject request',async d=>api('/api/bookings/'+encodeURIComponent(id)+'/status',{method:'PATCH',body:Object.assign(d,{status:'rejected'})}))} async function advanceBooking(id,status){try{await api(`/api/bookings/${encodeURIComponent(id)}/status`,{method:'PATCH',body:{status}});toast(`Booking ${id} updated: ${names[status]}.`);await reload()}catch(e){toast(e.message,true)}}
function toggleGps(id){if(app.watchId){stopGps();return}if(!navigator.geolocation){toast('This browser does not support GPS location.',true);return}const b=app.summary.bookings.find(x=>x.id===id);if(!b||b.status!=='in_transit'){toast('Mark the load in transit before sharing GPS.',true);return}app.selectedBooking=id;toast('GPS sharing started. Keep this page open; your device will ask permission.');app.watchId=navigator.geolocation.watchPosition(async pos=>{const now=Date.now();if(now-app.lastGpsSent<10000)return;app.lastGpsSent=now;try{await api(`/api/bookings/${encodeURIComponent(id)}/location`,{method:'PATCH',body:{latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy_m:pos.coords.accuracy,source:'browser GPS'}});await reload({quiet:true})}catch(e){toast(e.message,true);stopGps()}},{enableHighAccuracy:true,maximumAge:8000,timeout:20000});render()}
function stopGps(){if(app.watchId!=null)navigator.geolocation.clearWatch(app.watchId);app.watchId=null;app.selectedBooking=null;toast('GPS sharing stopped. The last point remains labelled with its update time.');render()}
function stopGpsIfChanging(page){if(app.watchId&&page!=='dispatch')stopGps()}
function bindGoto(){document.querySelectorAll('[data-goto]').forEach(x=>x.onclick=()=>go(x.dataset.goto))}
function go(page){app.page=page;render();window.scrollTo({top:0,behavior:'smooth'})}
async function enterAdmin(){try{const r=await fetch('/api/session',{credentials:'same-origin'}),data=await r.json();if(data.authenticated){app.mode='admin';app.role=data.role;app.staffUser=data.username;app.page=app.role==='recycler'?'intake':'dispatch';document.querySelector('#admin-role').value=app.role;await reload();return}showLogin(data.passcodeConfigured)}catch(e){toast(e.message,true)}} function showLogin(configured=true,selectedRole='operator'){const c=document.querySelector('#login-content'),disabled=configured?'':' disabled';c.innerHTML='<p class="eyebrow">SECURE STAFF ACCESS</p><h2 class="dialog-title">Sign in to a DEBRIX workspace</h2><p class="login-copy">Each session is bound to one staff role. Configure named staff accounts for record-level access.</p>'+(configured?'':'<div class="notice error"><strong>Staff access is not configured yet.</strong><p>Set DEBRIX_STAFF_ACCOUNTS_JSON or a role passcode in the server environment, then redeploy.</p></div>')+'<form id="login-form"><div class="field"><label for="login-role">Workspace</label><select id="login-role" name="role" required'+disabled+'><option value="operator"'+(selectedRole==='operator'?' selected':'')+'>Operator</option><option value="transporter"'+(selectedRole==='transporter'?' selected':'')+'>Transporter</option><option value="recycler"'+(selectedRole==='recycler'?' selected':'')+'>Recycler / facility</option></select></div><div class="field"><label for="staff-username">Staff account username</label><input id="staff-username" name="username" autocomplete="username" required pattern="[A-Za-z0-9][A-Za-z0-9._-]{1,39}" maxlength="40" placeholder="Example: driver-01"'+disabled+'></div><div class="field"><label for="admin-passcode">Passcode</label><input id="admin-passcode" name="passcode" type="password" autocomplete="current-password" required'+disabled+'></div><div class="form-error" id="login-error" role="alert"></div><div class="form-actions"><button class="button primary"'+disabled+' data-submit>Sign in</button></div></form><p class="source-line">Passcodes are verified by the backend and are never stored in browser code.</p>';document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.currentTarget),err=document.querySelector('#login-error');try{const r=await fetch('/api/session',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({role:form.get('role'),username:form.get('username'),passcode:form.get('passcode')})}),data=await r.json();if(!r.ok)throw new Error(data.error||'Could not sign in.');document.querySelector('#login-dialog').close();app.mode='admin';app.role=data.role;app.staffUser=data.username;app.page=app.role==='recycler'?'intake':'dispatch';document.querySelector('#admin-role').value=app.role;await reload()}catch(x){err.textContent=x.message}};document.querySelector('#login-dialog').showModal();setTimeout(()=>document.querySelector('#staff-username')?.focus(),50)} async function logout(){stopGps();await fetch('/api/session',{method:'DELETE',credentials:'same-origin'});app.mode='citizen';app.role='citizen';app.page='home';app.staffUser='';await reload();toast('Staff session ended.')}
async function changePortal(){stopGps();app.mode='citizen';app.role='citizen';app.page='home';await reload()}
async function changeAdminRole(role){if(!['operator','transporter','recycler'].includes(role)||role===app.role)return;stopGps();await fetch('/api/session',{method:'DELETE',credentials:'same-origin'});app.mode='citizen';app.role='citizen';app.staffUser='';app.page='home';showLogin(true,role)}
function applyTheme(){const dark=(localStorage.getItem('debrix-theme')||'light')==='dark';document.documentElement.dataset.theme=dark?'dark':'light';const b=document.querySelector('#theme-button');b.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} theme`);b.title=`Switch to ${dark?'light':'dark'} theme`}
document.querySelector('#theme-button').onclick=()=>{localStorage.setItem('debrix-theme',(localStorage.getItem('debrix-theme')||'light')==='dark'?'light':'dark');applyTheme()};
document.querySelector('#refresh-button').onclick=()=>reload();
document.querySelector('#citizen-portal').onclick=changePortal;
document.querySelector('#admin-portal').onclick=enterAdmin;
document.querySelector('#logout-button').onclick=logout;
document.querySelector('#admin-role').onchange=e=>changeAdminRole(e.target.value);
applyTheme();
(async()=>{try{const r=await fetch('/api/session',{credentials:'same-origin'}),s=await r.json();if(s.authenticated){app.mode='admin';app.role=s.role;app.staffUser=s.username;app.page=app.role==='recycler'?'intake':'dispatch';document.querySelector('#admin-role').value=app.role}}catch{}await reload()})();
setInterval(()=>{if(document.visibilityState==='visible'&&app.page!=='book'&&!document.querySelector('#detail-dialog[open]')&&!document.querySelector('#login-dialog[open]'))reload({quiet:true})},12000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&app.page!=='book'&&!document.querySelector('#detail-dialog[open]'))reload({quiet:true})});

